-- SACRIFICIO RPG - Supabase schema V1
-- Run this entire script once in Supabase Dashboard > SQL Editor.
-- It creates game_* tables only. It does not change clan tables except adding a trigger
-- to public.profiles so new member profiles receive an empty RPG profile.
-- All progression writes are server-only for now; authenticated users receive SELECT only.

begin;

-- ---------------------------------------------------------------------------
-- 1. STATIC CATALOG TABLES
-- ---------------------------------------------------------------------------

create table if not exists public.game_items (
  id integer primary key,
  item_key text not null unique,
  name text not null,
  category text not null,
  source text not null default '',
  stackable boolean not null default true,
  taggable boolean not null default false,
  visible_at_start boolean not null default false,
  method_enabled boolean not null default false,
  unlock_key text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.game_tags (
  id integer primary key,
  tag_key text not null unique,
  name text not null,
  tag_group text not null check (tag_group in ('rarity', 'affinity', 'element', 'special'))
);

create table if not exists public.game_discoveries (
  id integer primary key,
  discovery_key text not null unique,
  name text not null,
  permanent boolean not null default true,
  unlocks text,
  metadata jsonb not null default '{}'::jsonb
);

create table if not exists public.game_fishing_areas (
  id integer primary key,
  area_key text not null unique,
  name text not null,
  sort_order integer not null,
  unlock_key text,
  metadata jsonb not null default '{}'::jsonb
);

create table if not exists public.game_fishing_area_items (
  area_id integer not null references public.game_fishing_areas(id) on delete restrict,
  fish_item_id integer not null references public.game_items(id) on delete restrict,
  sort_order integer not null,
  primary key (area_id, fish_item_id),
  unique (area_id, sort_order)
);

create table if not exists public.game_baits (
  item_id integer primary key references public.game_items(id) on delete restrict,
  luck_bonus numeric(8,3),
  time_reduction_percent numeric(5,2),
  method_enabled boolean not null default false,
  metadata jsonb not null default '{}'::jsonb,
  check (time_reduction_percent is null or time_reduction_percent between 0 and 95)
);

create table if not exists public.game_station_catalog (
  id integer primary key,
  station_key text not null unique,
  name text not null,
  buildable boolean not null default true,
  unlock_key text,
  metadata jsonb not null default '{}'::jsonb
);

create table if not exists public.game_recipes (
  id integer primary key,
  recipe_key text not null unique,
  name text not null,
  status text not null default 'planned',
  station_id integer references public.game_station_catalog(id) on delete restrict,
  requires_badge_key text,
  metadata jsonb not null default '{}'::jsonb
);

create table if not exists public.game_recipe_ingredients (
  id bigint generated by default as identity primary key,
  recipe_id integer not null references public.game_recipes(id) on delete cascade,
  item_id integer not null references public.game_items(id) on delete restrict,
  quantity bigint not null check (quantity > 0),
  required_tag_ids integer[] not null default '{}'::integer[],
  ingredient_group integer not null default 1,
  notes text
);

create table if not exists public.game_recipe_outputs (
  id bigint generated by default as identity primary key,
  recipe_id integer not null references public.game_recipes(id) on delete cascade,
  item_id integer not null references public.game_items(id) on delete restrict,
  quantity bigint not null check (quantity > 0),
  tag_ids integer[] not null default '{}'::integer[]
);

-- ---------------------------------------------------------------------------
-- 2. PLAYER DATA TABLES
-- ---------------------------------------------------------------------------

create table if not exists public.game_profiles (
  player_id uuid primary key references auth.users(id) on delete cascade,
  gold bigint not null default 0 check (gold >= 0),
  lifetime_gold_earned bigint not null default 0 check (lifetime_gold_earned >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Slot capacity is derived from clan achievements. Do not store a duplicate slot_count here.
create table if not exists public.game_farms (
  player_id uuid primary key references public.game_profiles(player_id) on delete cascade,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.game_plots (
  id uuid primary key default gen_random_uuid(),
  player_id uuid not null references public.game_profiles(player_id) on delete cascade,
  slot_index integer not null check (slot_index >= 0),
  plant_item_id integer not null references public.game_items(id) on delete restrict,
  seed_item_id integer references public.game_items(id) on delete restrict,
  planted_at timestamptz not null,
  finishes_at timestamptz not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (finishes_at > planted_at),
  unique (player_id, slot_index)
);

-- tag_ids is intentionally stored in the same row as the item identity.
-- Different tag combinations are different inventory stacks.
create table if not exists public.game_inventory (
  id bigint generated by default as identity primary key,
  player_id uuid not null references public.game_profiles(player_id) on delete cascade,
  item_id integer not null references public.game_items(id) on delete restrict,
  quantity bigint not null check (quantity > 0),
  tag_ids integer[] not null default '{}'::integer[],
  instance_id uuid,
  instance_data jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index if not exists game_inventory_stack_unique
  on public.game_inventory (player_id, item_id, tag_ids)
  where instance_id is null;

create unique index if not exists game_inventory_instance_unique
  on public.game_inventory (player_id, instance_id)
  where instance_id is not null;

create table if not exists public.game_unlocks (
  player_id uuid not null references public.game_profiles(player_id) on delete cascade,
  discovery_id integer not null references public.game_discoveries(id) on delete restrict,
  discovered_at timestamptz not null default now(),
  metadata jsonb not null default '{}'::jsonb,
  primary key (player_id, discovery_id)
);

create table if not exists public.game_pity_counters (
  player_id uuid not null references public.game_profiles(player_id) on delete cascade,
  counter_key text not null,
  failures bigint not null default 0 check (failures >= 0),
  updated_at timestamptz not null default now(),
  primary key (player_id, counter_key)
);

create table if not exists public.game_stations (
  player_id uuid not null references public.game_profiles(player_id) on delete cascade,
  station_id integer not null references public.game_station_catalog(id) on delete restrict,
  level integer not null default 1 check (level >= 1),
  built_at timestamptz not null default now(),
  metadata jsonb not null default '{}'::jsonb,
  primary key (player_id, station_id)
);

create table if not exists public.game_fishing_jobs (
  id uuid primary key default gen_random_uuid(),
  player_id uuid not null references public.game_profiles(player_id) on delete cascade,
  area_id integer not null references public.game_fishing_areas(id) on delete restrict,
  fish_item_id integer not null references public.game_items(id) on delete restrict,
  bait_item_id integer references public.game_baits(item_id) on delete restrict,
  started_at timestamptz not null default now(),
  finishes_at timestamptz not null,
  completed_at timestamptz,
  status text not null default 'active' check (status in ('active', 'completed', 'cancelled')),
  result_snapshot jsonb not null default '{}'::jsonb,
  check (finishes_at > started_at)
);

create unique index if not exists game_one_active_fishing_job_per_player
  on public.game_fishing_jobs (player_id)
  where status = 'active';

create table if not exists public.game_mining_runs (
  id uuid primary key default gen_random_uuid(),
  player_id uuid not null references public.game_profiles(player_id) on delete cascade,
  tool_item_id integer references public.game_items(id) on delete restrict,
  started_at timestamptz not null default now(),
  completed_at timestamptz,
  status text not null default 'active' check (status in ('active', 'completed', 'cancelled')),
  result_snapshot jsonb not null default '{}'::jsonb
);

create table if not exists public.game_crafting_jobs (
  id uuid primary key default gen_random_uuid(),
  player_id uuid not null references public.game_profiles(player_id) on delete cascade,
  recipe_id integer not null references public.game_recipes(id) on delete restrict,
  input_snapshot jsonb not null default '[]'::jsonb,
  output_snapshot jsonb not null default '[]'::jsonb,
  started_at timestamptz not null default now(),
  finishes_at timestamptz,
  completed_at timestamptz,
  status text not null default 'active' check (status in ('active', 'completed', 'cancelled')),
  created_at timestamptz not null default now()
);

create table if not exists public.game_transactions (
  id uuid primary key default gen_random_uuid(),
  player_id uuid not null references public.game_profiles(player_id) on delete cascade,
  event_key text not null,
  gold_delta bigint not null default 0,
  item_changes jsonb not null default '[]'::jsonb,
  reference_id uuid,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
