-- 4. TAG VALIDATION AND PROFILE INITIALIZATION
-- ---------------------------------------------------------------------------

create or replace function public.game_prepare_inventory_stack()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_taggable boolean;
  v_stackable boolean;
begin
  if new.quantity is null or new.quantity <= 0 then
    raise exception 'Inventory quantity must be greater than zero.';
  end if;

  select taggable, stackable
    into v_taggable, v_stackable
    from public.game_items
   where id = new.item_id;

  if not found then
    raise exception 'Unknown game item id: %', new.item_id;
  end if;

  select coalesce(array_agg(distinct supplied.tag_id order by supplied.tag_id), '{}'::integer[])
    into new.tag_ids
    from unnest(coalesce(new.tag_ids, '{}'::integer[])) as supplied(tag_id);

  if exists (
    select 1
      from unnest(new.tag_ids) as supplied(tag_id)
      left join public.game_tags tag on tag.id = supplied.tag_id
     where tag.id is null
  ) then
    raise exception 'Inventory contains an unknown tag id.';
  end if;

  if exists (
    select tag.tag_group
      from unnest(new.tag_ids) as supplied(tag_id)
      join public.game_tags tag on tag.id = supplied.tag_id
     group by tag.tag_group
    having count(*) > 1
  ) then
    raise exception 'Only one tag per tag group is allowed on an item stack.';
  end if;

  if cardinality(new.tag_ids) > 0 and not v_taggable then
    raise exception 'This catalog item does not accept tags.';
  end if;

  if not v_stackable and (new.instance_id is null or new.quantity <> 1) then
    raise exception 'Non-stackable items require instance_id and quantity = 1.';
  end if;

  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists trg_game_inventory_prepare_stack on public.game_inventory;
create trigger trg_game_inventory_prepare_stack
before insert or update of item_id, quantity, tag_ids, instance_id
on public.game_inventory
for each row execute function public.game_prepare_inventory_stack();

create or replace function public.game_set_updated_at()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists trg_game_profiles_updated_at on public.game_profiles;
create trigger trg_game_profiles_updated_at
before update on public.game_profiles
for each row execute function public.game_set_updated_at();

drop trigger if exists trg_game_farms_updated_at on public.game_farms;
create trigger trg_game_farms_updated_at
before update on public.game_farms
for each row execute function public.game_set_updated_at();

drop trigger if exists trg_game_plots_updated_at on public.game_plots;
create trigger trg_game_plots_updated_at
before update on public.game_plots
for each row execute function public.game_set_updated_at();

create or replace function public.game_create_farm_for_game_profile()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.game_farms (player_id)
  values (new.player_id)
  on conflict (player_id) do nothing;
  return new;
end;
$$;

drop trigger if exists trg_game_profile_create_farm on public.game_profiles;
create trigger trg_game_profile_create_farm
after insert on public.game_profiles
for each row execute function public.game_create_farm_for_game_profile();

-- Existing profiles receive an empty game profile and an empty farm.
insert into public.game_profiles (player_id)
select id from public.profiles
on conflict (player_id) do nothing;

insert into public.game_farms (player_id)
select player_id from public.game_profiles
on conflict (player_id) do nothing;

-- Future public.profiles rows receive a game profile automatically.
create or replace function public.game_create_profile_for_clan_member()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.game_profiles (player_id)
  values (new.id)
  on conflict (player_id) do nothing;
  return new;
end;
$$;

drop trigger if exists trg_game_profile_after_clan_profile_insert on public.profiles;
create trigger trg_game_profile_after_clan_profile_insert
after insert on public.profiles
for each row execute function public.game_create_profile_for_clan_member();

-- ---------------------------------------------------------------------------
-- 5. INDEXES
-- ---------------------------------------------------------------------------

create index if not exists game_inventory_player_item_idx
  on public.game_inventory (player_id, item_id);

create index if not exists game_plots_player_idx
  on public.game_plots (player_id);

create index if not exists game_unlocks_player_idx
  on public.game_unlocks (player_id);

create index if not exists game_transactions_player_created_idx
  on public.game_transactions (player_id, created_at desc);

create index if not exists game_fishing_jobs_player_status_idx
  on public.game_fishing_jobs (player_id, status);

create index if not exists game_crafting_jobs_player_status_idx
  on public.game_crafting_jobs (player_id, status);

-- ---------------------------------------------------------------------------
-- 6. ROW LEVEL SECURITY
-- Static catalogs are readable by authenticated users. Player records are
-- readable only by their owner. No client-side writes are granted in V1.
-- ---------------------------------------------------------------------------

do $$
declare
  table_name text;
begin
  foreach table_name in array array[
    'game_items',
    'game_tags',
    'game_discoveries',
    'game_fishing_areas',
    'game_fishing_area_items',
    'game_baits',
    'game_station_catalog',
    'game_recipes',
    'game_recipe_ingredients',
    'game_recipe_outputs'
  ] loop
    execute format('alter table public.%I enable row level security', table_name);
    execute format('drop policy if exists game_catalog_read on public.%I', table_name);
    execute format(
      'create policy game_catalog_read on public.%I for select to authenticated using (true)',
      table_name
    );
    execute format('revoke all on table public.%I from anon, authenticated', table_name);
    execute format('grant select on table public.%I to authenticated', table_name);
    execute format('grant all on table public.%I to service_role', table_name);
  end loop;

  foreach table_name in array array[
    'game_profiles',
    'game_farms',
    'game_plots',
    'game_inventory',
    'game_unlocks',
    'game_pity_counters',
    'game_stations',
    'game_fishing_jobs',
    'game_mining_runs',
    'game_crafting_jobs',
    'game_transactions'
  ] loop
    execute format('alter table public.%I enable row level security', table_name);
    execute format('drop policy if exists game_read_own on public.%I', table_name);
    execute format(
      'create policy game_read_own on public.%I for select to authenticated using (player_id = auth.uid())',
      table_name
    );
    execute format('revoke all on table public.%I from anon, authenticated', table_name);
    execute format('grant select on table public.%I to authenticated', table_name);
    execute format('grant all on table public.%I to service_role', table_name);
  end loop;
end;
$$;

grant usage on schema public to authenticated;
grant usage, select on all sequences in schema public to service_role;

-- No INSERT/UPDATE/DELETE policy exists for authenticated users yet.
-- Future mutations should be added as server-validated RPC/Edge Functions,
-- not direct browser writes.

commit;

